function flattenOne(arr) {
  // Flattens exactly ONE level deep: [1, [2, 3], [[4]]] -> [1, 2, 3, [4]].
  // Non-array elements pass through unchanged.
  const out = [];
  for (const item of arr) {
    if (Array.isArray(item)) {
      for (const inner of item) {
        out.push(inner);
      }
    } else {
      out.push(item);
    }
  }
  return out;
}

module.exports = { flattenOne };

