const { execFileSync } = require("node:child_process");
const fs = require("node:fs");

const IMPL = "flatten.js";
const MUTANTS = [
  // flattens fully (recurses into nested arrays) instead of one level
  ['      for (const inner of item) {\n        out.push(inner);\n      }',
   '      out.push(...item.flat(Infinity));'],
  // non-array elements dropped instead of passed through
  ['    } else {\n      out.push(item);\n    }',
   '    }'],
  // empty nested arrays leave a stray undefined
  ['  for (const item of arr) {',
   '  for (const item of arr) {\n    if (Array.isArray(item) && item.length === 0) { out.push(undefined); continue; }'],
];

function runTests() {
  try {
    execFileSync(process.execPath, ["--test", "test_flatten.js"], { stdio: "inherit" });
    return 0;
  } catch {
    return 1;
  }
}

const src = fs.readFileSync(IMPL, "utf8");
for (const [old] of MUTANTS) {
  if (src.split(old).length - 1 !== 1) {
    console.error(`protected implementation file ${IMPL} was modified - anchor not found exactly once: ${JSON.stringify(old)}`);
    process.exit(1);
  }
}

if (runTests() !== 0) {
  console.error("model tests FAILED against the correct implementation");
  process.exit(1);
}

let failed = false;
try {
  for (let i = 0; i < MUTANTS.length; i++) {
    fs.writeFileSync(IMPL, src.replace(MUTANTS[i][0], MUTANTS[i][1]));
    if (runTests() === 0) {
      console.error(`mutation ${i + 1} SURVIVED: the tests do not verify the required behavior`);
      failed = true;
      break;
    }
  }
} finally {
  fs.writeFileSync(IMPL, src);
}
if (failed) process.exit(1);
console.log(`PASS (killed all ${MUTANTS.length} mutants)`);

