const test = require("node:test");
const assert = require("node:assert");
const { flattenOne } = require("./flatten");

test("mix of flat and nested elements", () => {
  assert.deepStrictEqual(flattenOne([1, [2, 3], 4]), [1, 2, 3, 4]);
});

test("only one level is flattened", () => {
  assert.deepStrictEqual(flattenOne([1, [2, [3, 4]]]), [1, 2, [3, 4]]);
});

test("empty nested array contributes nothing", () => {
  assert.deepStrictEqual(flattenOne([1, [], 2]), [1, 2]);
});

test("already-flat array is unchanged", () => {
  assert.deepStrictEqual(flattenOne([1, 2, 3]), [1, 2, 3]);
});

test("empty input", () => {
  assert.deepStrictEqual(flattenOne([]), []);
});

