const test = require("node:test");
const assert = require("node:assert");
const { flattenOne } = require("./flatten");

test("returns an array", () => {
  assert.ok(Array.isArray(flattenOne([1, [2]])));
});

test("result is not longer than reasonable", () => {
  assert.ok(flattenOne([1, [2, 3]]).length <= 3);
});

test("empty input gives empty output", () => {
  assert.deepStrictEqual(flattenOne([]), []);
});

test("contains the flat elements", () => {
  assert.ok(flattenOne([1, [2]]).includes(1));
});
